insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('209', 'Founder Psychology', '2026-07-15 11:04:40.669009+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Founder recalls their own explanation clearly and treats the other person''s reaction as one data point, not a verdict.', '["all"]', 'false', 'Stage 0', 'CORE', '96', 'S0-PSY-001', 'You told someone close to you about this idea recently. Walk me through exactly what you said and how they reacted.', 'open_text', 'Founder focuses on the reaction they got (or feared) more than what they actually said about the idea — approval-seeking framing, not idea-clarity framing.', '529', '2026-07-15 11:04:40.669009+00') on conflict do nothing;
