insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('256', 'Product', '2026-07-15 14:00:12.839953+00', '2', '1536', 'text-embedding-3-small', NULL, NULL, 'Gives a real, considered estimate, even if approximate.', '["all"]', 'false', 'Stage 0→1', 'SUPPLEMENTARY', '33', 'S01-PRD-006', 'Without checking, what percentage of users used your product this week?', 'open_text', 'Cannot produce even a rough estimate, suggesting usage isn''t being tracked or watched at all.', '382', '2026-07-15 14:00:12.839953+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('257', 'Team & Leadership', '2026-07-15 14:00:12.839953+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Redid it only for a genuine quality issue, and gave feedback rather than silently replacing the work.', '["all"]', 'false', 'Stage 1→10+', 'CORE', '25', 'S10-TM-001', 'Tell me about the last time you rewrote or redid someone else''s completed work. What made you do it?', 'open_text', 'Redid it purely because it wasn''t done their exact way, not because it was genuinely wrong or below standard.', '226', '2026-07-15 14:00:12.839953+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('258', 'Team & Leadership', '2026-07-15 14:00:12.839953+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Went ahead for a specific, considered reason despite the doubt, with a plan to evaluate quickly.', '["all"]', 'false', 'Stage 1→10+', 'SUPPLEMENTARY', '23', 'S10-TM-002', 'Describe your most recent hiring decision you''re still unsure about. What made you go ahead anyway?', 'open_text', 'Went ahead purely out of urgency or desperation to fill the role, overriding real doubts.', '237', '2026-07-15 14:00:12.839953+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('259', 'Team & Leadership', '2026-07-15 14:00:12.839953+00', '4', '1536', 'text-embedding-3-small', NULL, NULL, 'Can name it honestly and recognizes the discomfort is about control, not actual quality.', '["all"]', 'false', 'Stage 1→10+', 'CORE', '25', 'S10-TM-003', 'What''s a responsibility you''d genuinely struggle to watch someone else do differently than you, even if their way worked fine?', 'open_text', 'Cannot separate ''differently'' from ''wrong'' — any deviation from their own method feels like a real problem.', '236', '2026-07-15 14:00:12.839953+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('260', 'Team & Leadership', '2026-07-15 14:00:12.839953+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Recognizes deliberate variety, or names the similarity honestly as something to watch.', '["all"]', 'false', 'Stage 1→10+', 'CORE', '23', 'S10-TM-004', 'Look at your last 3 hires — how similar are they to you and to each other?', 'open_text', 'Recognizes a strong, unexamined pattern of hiring people who think and act like them.', '239', '2026-07-15 14:00:12.839953+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('261', 'Team & Leadership', '2026-07-15 14:00:12.839953+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Made a considered call under pressure, and it has genuinely worked out or was corrected quickly.', '["all"]', 'false', 'Stage 1→10+', 'SUPPLEMENTARY', '23', 'S10-TM-005', 'Tell me about a hire you made under real time pressure. How''s that decision held up since?', 'open_text', 'Made the hire purely to fill an urgent gap, and it has since caused ongoing problems they''re managing around rather than addressing.', '237', '2026-07-15 14:00:12.839953+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('262', 'Team & Leadership', '2026-07-15 14:00:12.839953+00', '4', '1536', 'text-embedding-3-small', NULL, NULL, 'Can articulate the difference clearly between what the business needs and what''s just their own personal habit.', '["all"]', 'false', 'Stage 1→10+', 'CORE', '25', 'S10-TM-006', 'If someone else ran this business exactly your way for a month, what would feel wrong about it, even if it worked?', 'open_text', 'Struggles to separate the business''s actual needs from their own personal identity being tied to running it a specific way.', '228', '2026-07-15 14:00:12.839953+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('263', 'Fundraising', '2026-07-15 14:00:12.839953+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Uneasy but able to give a specific, honest answer about a known gap and the plan to close it.', '["all"]', 'false', 'Stage 1→10+', 'CORE', '26', 'S10-FND-001', 'Tell me about the last time an investor asked about your team and you felt uneasy answering.', 'open_text', 'Uneasy because a real gap exists in team strength that hasn''t been addressed, only worked around.', '303', '2026-07-15 14:00:12.839953+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('264', 'Fundraising', '2026-07-15 14:00:12.839953+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Names specific hires, milestones, or initiatives tied to real numbers and timelines.', '["all"]', 'false', 'Stage 1→10+', 'CORE', '26', 'S10-FND-002', 'If you raised money tomorrow, what specifically would change in the next 90 days?', 'open_text', 'Answer is vague (''grow faster'', ''hire more'') without specific roles, milestones, or numbers attached.', '306', '2026-07-15 14:00:12.839953+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('265', 'Fundraising', '2026-07-15 14:00:12.839953+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Either the numbers aligned, or they clearly noticed and understood the mismatch afterward.', '["all"]', 'false', 'Stage 1→10+', 'SUPPLEMENTARY', '26', 'S10-FND-003', 'Describe your last investor conversation. What number were you proudest of, and did they seem to agree it mattered?', 'open_text', 'The number they were proud of wasn''t the one the investor cared about, and they didn''t notice the mismatch.', '297', '2026-07-15 14:00:12.839953+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('266', 'Fundraising', '2026-07-15 14:00:12.839953+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Included real problems alongside progress, or has a clear, defensible reason for a specific omission.', '["all"]', 'true', 'Stage 1→10+', 'CORE', '26', 'S10-FND-004', 'Tell me about the last time you updated investors. What did you leave out, and why?', 'open_text', 'Left out a real problem specifically to avoid a difficult conversation or appearing weak.', '310', '2026-07-15 14:00:12.839953+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('267', 'Fundraising', '2026-07-15 14:00:12.839953+00', '4', '1536', 'text-embedding-3-small', NULL, NULL, 'Gives a clear, specific one-sentence answer distinguishing today''s model from the at-scale model.', '["all"]', 'false', 'Stage 1→10+', 'CORE', '26', 'S10-FND-005', 'Explain, in one sentence, exactly how this business makes money at scale — not how it makes money today.', 'open_text', 'Can only describe how revenue works today, with no clear model for how margins or mechanics change at scale.', '307', '2026-07-15 14:00:12.839953+00') on conflict do nothing;
