insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('269', 'Operations & Systems', '2026-07-15 14:13:22.513349+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Has started noticing the repetition and either wrote something down or built a simple repeatable approach.', '["all"]', 'false', 'Stage 0→1', 'CORE', '40', 'S01-OPS-001', 'Walk me through how you handled the last recurring task you did for the third time. Did you do it the same way, or figure it out fresh again?', 'open_text', 'Redoes recurring tasks from scratch each time with no written or repeatable method emerging.', '457', '2026-07-15 14:13:22.513349+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('270', 'Operations & Systems', '2026-07-15 14:13:22.513349+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Names specific things that would pause, but at least one core activity could continue via someone else.', '["all"]', 'false', 'Stage 0→1', 'CORE', '40', 'S01-OPS-002', 'If you got sick for a week right now, what would simply stop happening in the business?', 'open_text', 'Names core activities that would fully halt, with no one else able to pick them up even temporarily.', '460', '2026-07-15 14:13:22.513349+00') on conflict do nothing;
