insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('286', 'Fundraising', '2026-07-15 14:13:22.513349+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Has real, considered criteria for whose money to take, even this early.', '["all"]', 'false', 'Stage 0→1', 'SUPPLEMENTARY', '30', 'S01-FND-006', 'If you removed your company name from your vision statement, could it belong to any other startup in your space?', 'open_text', 'Vision statement lacks specificity unique to this company', '314', '2026-07-15 14:13:22.513349+00') on conflict do nothing;
