insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('304', 'Product', '2026-07-15 14:13:22.513349+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Names a specific way this would be caught — monitoring, feedback loops, or direct observation.', '["all"]', 'false', 'Stage 1→10+', 'CORE', '36', 'S10-PRD-006', 'If a customer''s first experience with your product today was as rough as it was in your very first month, would you notice? How?', 'open_text', 'Would likely not notice — no clear system exists to catch first-impression quality regressions at current scale.', '417', '2026-07-15 14:13:22.513349+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('305', 'Founder Psychology', '2026-07-16 12:24:17.901932+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Recalls a specific real moment, place, and trigger with real detail.', '["all"]', 'false', 'Stage 0', 'CORE', '123', 'S0-PSY-006', 'Picture the moment this idea first properly grabbed you — where were you, and what actually triggered it?', 'open_text', 'Cannot recall a specific real moment — the origin is vague or reconstructed after the fact rather than genuinely remembered.', '518', '2026-07-16 12:24:17.901932+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('306', 'Founder Psychology', '2026-07-16 12:24:17.901932+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'The line centers on the problem/person being served, not on self-image or external validation.', '["all"]', 'false', 'Stage 0', 'CORE', '96', 'S0-PSY-007', 'Tell me about the last piece of harsh feedback or rejection you got. How long did it actually stay with you?', 'open_text', 'Rejection causes disproportionate, lingering distress', '531', '2026-07-16 12:24:17.901932+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('307', 'Founder Psychology', '2026-07-16 12:24:17.901932+00', '2', '1536', 'text-embedding-3-small', NULL, NULL, 'Names a clear standard and can explain why that one matters most to them specifically.', '["all"]', 'false', 'Stage 0', 'CORE', '123', 'S0-PSY-008', 'When you picture doing this really well, what does ''well'' actually mean to you — being first, being the best, or being trusted?', 'open_text', 'Answer is driven by comparison to others (first/best) rather than an internal standard, with no room for ''good enough for now.''', '519', '2026-07-16 12:24:17.901932+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('308', 'Founder Psychology', '2026-07-16 12:24:17.901932+00', '4', '1536', 'text-embedding-3-small', NULL, NULL, 'First reaction includes genuine curiosity or a specific counter-point, even alongside the sting.', '["all"]', 'true', 'Stage 0', 'CORE', '123', 'S0-PSY-009', 'Someone far more experienced than you dismisses your idea in one sentence. What''s your honest first internal reaction — before you compose yourself?', 'open_text', 'First reaction is shame or an urge to quit/hide, rather than curiosity about whether the criticism has merit.', '520', '2026-07-16 12:24:17.901932+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('309', 'Founder Psychology', '2026-07-16 12:24:17.901932+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'The reason is specific and self-owned, not borrowed from someone else''s expectation.', '["all"]', 'false', 'Stage 0', 'CORE', '123', 'S0-PSY-010', 'In one sentence, why does this problem deserve your next few years?', 'open_text', 'The reason given is externally imposed (family/social expectation) rather than something the founder actually owns.', '522', '2026-07-16 12:24:17.901932+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('310', 'Founder Psychology', '2026-07-16 12:24:17.901932+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Gives a concrete, specific picture defined on its own terms, not purely by comparison to others.', '["all"]', 'false', 'Stage 0', 'CORE', '123', 'S0-PSY-011', 'Picture this venture thriving five years from now — what does ''thriving'' actually look like, concretely?', 'open_text', 'Vision is defined entirely relative to competitors or others'' success, with no concrete, self-defined picture.', '526', '2026-07-16 12:24:17.901932+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('311', 'Founder Psychology', '2026-07-16 12:24:17.901932+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Answer centers clearly and specifically on the people being served.', '["all"]', 'false', 'Stage 0', 'CORE', '96', 'S0-PSY-012', 'If this succeeds completely, what changes for the people you''re building it for?', 'open_text', 'Answer centers on what changes for the founder personally rather than for the people being served.', '530', '2026-07-16 12:24:17.901932+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('312', 'Founder Psychology', '2026-07-16 12:24:17.901932+00', '2', '1536', 'text-embedding-3-small', NULL, NULL, 'Gives an honest answer either way, with a real reason behind the preference, not just a fear-driven default.', '["all"]', 'false', 'Stage 0', 'SUPPLEMENTARY', '96', 'S0-PSY-013', 'When you face a big unknown, do you decide fast and adjust as you go, or gather everything you can before you move?', 'open_text', 'Says ''gather everything'' but the real reason is fear of a wrong decision rather than genuine diligence.', '537', '2026-07-16 12:24:17.901932+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('313', 'Founder Psychology', '2026-07-16 12:24:17.901932+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Describes a grounded, specific real response, even if imperfect.', '["all"]', 'true', 'Stage 0', 'CORE', '123', 'S0-PSY-014', 'Think of the last time you faced real uncertainty outside of work. What did you actually do — not what you wish you''d done?', 'open_text', 'Describes catastrophizing or worst-case spiraling as the actual response, not just a passing thought.', '524', '2026-07-16 12:24:17.901932+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('314', 'Founder Psychology', '2026-07-16 12:24:17.901932+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Advice is specific and grounded, suggesting real reflection rather than a generic platitude.', '["all"]', 'false', 'Stage 0', 'SUPPLEMENTARY', '123', 'S0-PSY-015', 'If your future self, five years into this, sent you one sentence of advice right now — what would it say?', 'open_text', 'Advice is generic reassurance (''it''ll be fine'') rather than something specific to this founder''s real situation.', '525', '2026-07-16 12:24:17.901932+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('315', 'Founder Psychology', '2026-07-16 12:24:17.901932+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Names a specific, concrete behavioral difference, not just a vague sense of ''more confident.''', '["all"]', 'false', 'Stage 0→1', 'CORE', '110', 'S01-PSY-006', 'What''s actually different about how you show up now versus before you started building?', 'open_text', 'Cannot name a real, specific difference — suggests limited reflection on their own growth.', '544', '2026-07-16 12:24:17.901932+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('316', 'Founder Psychology', '2026-07-16 12:24:17.901932+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Recalls a specific instance and a clear, considered reason for shipping anyway.', '["all"]', 'false', 'Stage 0→1', 'CORE', '122', 'S01-PSY-007', 'Tell me about the last thing you shipped that you weren''t fully happy with, but shipped anyway. Why?', 'open_text', 'Cannot recall ever doing this — suggests standards may be blocking real shipping momentum.', '577', '2026-07-16 12:24:17.901932+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('317', 'Founder Psychology', '2026-07-16 12:24:17.901932+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Names one specific, concrete metric clearly.', '["all"]', 'false', 'Stage 0→1', 'CORE', '122', 'S01-PSY-008', 'What''s the one number that, if it moved, would tell you this is really working?', 'open_text', 'Cannot name a specific number — suggests progress is being judged by feeling rather than evidence.', '590', '2026-07-16 12:24:17.901932+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('318', 'Founder Psychology', '2026-07-16 12:24:17.901932+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Gives a clear one-sentence answer and can honestly describe how/why it evolved, if it did.', '["all"]', 'false', 'Stage 0→1', 'CORE', '99', 'S01-PSY-009', 'When someone else on your team makes a mistake, does it feel worse than when you make one yourself?', 'open_text', 'Others'' mistakes feel disproportionately costly due to founder accountability', '576', '2026-07-16 12:24:17.901932+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('319', 'Founder Psychology', '2026-07-16 12:24:17.901932+00', '4', '1536', 'text-embedding-3-small', NULL, NULL, 'Reached out or explicitly reprioritized, even if imperfectly.', '["all"]', 'true', 'Stage 0→1', 'SUPPLEMENTARY', '110', 'S01-PSY-010', 'Walk me through the last time you were completely overwhelmed. What did you actually do — push through, shut down, or reach out?', 'open_text', 'Pushed through or shut down silently, with no one else informed until well after the fact.', '552', '2026-07-16 12:24:17.901932+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('320', 'Founder Psychology', '2026-07-16 12:24:17.901932+00', '2', '1536', 'text-embedding-3-small', NULL, NULL, 'Gives a clear, self-aware answer consistent with how they''ve actually responded to bad news in the past.', '["all"]', 'false', 'Stage 0→1', 'SUPPLEMENTARY', '122', 'S01-PSY-011', 'When something''s going wrong, do you want it told to you straight, laid out step by step, or talked through out loud?', 'open_text', 'Cannot answer clearly, or the stated preference contradicts how they''ve actually reacted to bad news before.', '599', '2026-07-16 12:24:17.901932+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('321', 'Founder Psychology', '2026-07-16 12:24:17.901932+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Names something specific and gives a real, considered reason for the tradeoff.', '["all"]', 'false', 'Stage 0→1', 'CORE', '122', 'S01-PSY-012', 'What''s the thing you''re doing right now that isn''t scalable, but you''re doing anyway — and why?', 'open_text', 'Cannot name anything — suggests limited awareness of their own unsustainable habits.', '596', '2026-07-16 12:24:17.901932+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('322', 'Founder Psychology', '2026-07-16 12:24:17.901932+00', '4', '1536', 'text-embedding-3-small', NULL, NULL, 'Shares something real and specific, even if brief.', '["all"]', 'true', 'Stage 0→1', 'CORE', '122', 'S01-PSY-013', 'Has a string of past setbacks made it harder to actually believe this one will work?', 'open_text', 'Accumulated past failures have eroded belief in current success', '589', '2026-07-16 12:24:17.901932+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('323', 'Founder Psychology', '2026-07-16 12:24:17.901932+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Names a specific, concrete evolution in how they lead, not just ''I''ve grown.''', '["all"]', 'false', 'Stage 1→10+', 'CORE', '123', 'S10-PSY-006', 'Who were you as a leader in year one, and who are you now — what''s the actual difference?', 'open_text', 'Cannot articulate a real difference — suggests the founder''s leadership identity hasn''t evolved alongside the business.', '517', '2026-07-16 12:24:17.901932+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('324', 'Founder Psychology', '2026-07-16 12:24:17.901932+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Recalls a specific real instance tied to genuine quality or values, not status.', '["all"]', 'false', 'Stage 1→10+', 'CORE', '96', 'S10-PSY-007', 'If you achieved something big but nobody else ever found out, would it still feel worth it?', 'open_text', 'Achievement feels hollow without social recognition', '555', '2026-07-16 12:24:17.901932+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('325', 'Founder Psychology', '2026-07-16 12:24:17.901932+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Names something specific and substantive that doesn''t depend on their day-to-day presence.', '["all"]', 'false', 'Stage 1→10+', 'CORE', '110', 'S10-PSY-008', 'If you stepped away for a year, what''s the one thing about this business you''d want to still be true when you came back?', 'open_text', 'Answer reveals the business cannot run without their direct control — no real answer beyond ''that it still runs.''', '541', '2026-07-16 12:24:17.901932+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('326', 'Founder Psychology', '2026-07-16 12:24:17.901932+00', '4', '1536', 'text-embedding-3-small', NULL, NULL, 'Can articulate the business''s future as something distinct from their own ongoing personal role in it.', '["all"]', 'false', 'Stage 1→10+', 'SUPPLEMENTARY', '123', 'S10-PSY-009', 'What does this venture being ''done'' even mean to you — does it end, or does it just change shape?', 'open_text', 'Cannot separate the business''s future from their own personal identity or involvement.', '527', '2026-07-16 12:24:17.901932+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('327', 'Founder Psychology', '2026-07-16 12:24:17.901932+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Recalls a specific instance with honest reflection on their own misjudgment and its real cost.', '["all"]', 'false', 'Stage 1→10+', 'CORE', '96', 'S10-PSY-010', 'Tell me about the last time you were wrong about a person on your team. What did that actually cost you?', 'open_text', 'Cannot recall one, or attributes the situation entirely to the other person with no self-reflection.', '560', '2026-07-16 12:24:17.901932+00') on conflict do nothing;
insert into "questions" ("question_id", "category", "created_at", "difficulty_level", "embedding_dimension", "embedding_model", "embedding_version", "follow_up_question_id", "green_flag_pattern", "industry_relevance", "is_distress_tagged", "primary_stage_group", "priority", "problem_id", "question_code", "question_text", "question_type", "red_flag_pattern", "root_cause_id", "updated_at") values ('328', 'Founder Psychology', '2026-07-16 12:24:17.901932+00', '3', '1536', 'text-embedding-3-small', NULL, NULL, 'Checks in only when needed or flagged, showing real trust in the handoff.', '["all"]', 'false', 'Stage 1→10+', 'CORE', '96', 'S10-PSY-011', 'When you hand something off, do you check in daily, weekly, or only when it''s flagged to you?', 'open_text', 'Checks in daily or more, revealing difficulty genuinely letting go despite calling it ''delegated.''', '557', '2026-07-16 12:24:17.901932+00') on conflict do nothing;
